def mark_existing_paid(apps_, schema_editor):
    """Purchases from before payments were tracked: the total is worked out, and each
    counts as paid in full when bought, with the method not recorded."""
    Purchase = apps_.get_model("inventory", "Purchase")
    SupplierPayment = apps_.get_model("inventory", "SupplierPayment")
    PaymentAllocation = apps_.get_model("inventory", "PaymentAllocation")
    numbers = {}
    for purchase in Purchase.objects.order_by("business_id", "purchased_at", "id"):
        total = sum((i.unit_cost * i.quantity for i in purchase.items.all()), 0)
        purchase.total = purchase.paid_amount = total
        purchase.save(update_fields=["total", "paid_amount"])
        numbers[purchase.business_id] = numbers.get(purchase.business_id, 0) + 1
        payment = SupplierPayment.objects.create(
            business_id=purchase.business_id, number=numbers[purchase.business_id], supplier_id=purchase.supplier_id,
            amount=total, method="", paid_at=purchase.purchased_at, created_by_id=purchase.created_by_id,
        )
        PaymentAllocation.objects.create(payment=payment, purchase=purchase, amount=total)


